<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;
use App\Services\StudentAdmissions;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\{DB,Storage};
use Illuminate\Validation\Rule;
use Illuminate\Database\QueryException;
class StudentsController extends Controller
{
 public function __construct(private StudentAdmissions $students){}
 private function locked(Request $r,callable $fn){[$sid,$campuses]=$this->students->context($r,true);try{return DB::transaction(function()use($sid,$campuses,$fn){DB::table('schools')->where('id',$sid)->lockForUpdate()->first();return $fn($sid,$campuses);});}catch(QueryException $e){if($e->getCode()==='23000')$this->students->fail('A duplicate or linked record prevents this change. Refresh and review the details.');throw $e;}}
 public function setup(Request $r){[$sid,$campuses]=$this->students->context($r);return response()->json(['can_manage'=>$this->students->access->can($r,'students.manage'),'campuses'=>$this->students->access->campuses($this->students->access->membership($r)),'sections'=>DB::table('sections as s')->join('classes as c','c.id','=','s.class_id')->join('academic_sessions as y','y.id','=','s.academic_session_id')->join('campuses as p','p.id','=','s.campus_id')->where('s.school_id',$sid)->whereIn('s.campus_id',$campuses)->orderByDesc('y.starts_on')->orderBy('c.position')->get(['s.*','c.name as class_name','y.name as session_name','y.status as session_status','p.name as campus_name','p.status as campus_status']),'sessions'=>DB::table('academic_sessions')->where('school_id',$sid)->orderByDesc('starts_on')->get(['id','name']),'classes'=>DB::table('classes')->where('school_id',$sid)->orderBy('position')->get(['id','name'])]);}
 public function index(Request $r){
  [$sid,$campuses]=$this->students->context($r);$d=$r->validate(['search'=>'nullable|string|max:100','campus_id'=>'nullable|integer','section_id'=>'nullable|integer','session_id'=>'nullable|integer','class_id'=>'nullable|integer','status'=>['nullable',Rule::in(['active','withdrawn','graduated'])],'page'=>'nullable|integer|min:1']);
  $q=$this->students->visible($sid,$campuses);
  if(!empty($d['search'])){$term='%'.str_replace(['\\','%','_'],['\\\\','\\%','\\_'],$d['search']).'%';$q->where(fn($q)=>$q->where('s.admission_no','like',$term)->orWhereRaw("CONCAT_WS(' ',s.first_name,s.last_name) LIKE ?",[$term]));}
  if(!empty($d['status']))$q->where('s.status',$d['status']);
  if(array_filter(array_intersect_key($d,array_flip(['campus_id','section_id','session_id','class_id']))))$q->whereExists(function($q)use($d,$campuses){$q->selectRaw('1')->from('enrollments as e')->join('sections as c','c.id','=','e.section_id')->whereColumn('e.school_id','s.school_id')->whereColumn('e.student_id','s.id')->whereIn('c.campus_id',$campuses);foreach(['campus_id'=>'c.campus_id','section_id'=>'c.id','session_id'=>'c.academic_session_id','class_id'=>'c.class_id'] as $key=>$column)if(!empty($d[$key]))$q->where($column,$d[$key]);});
  $rows=$q->orderByDesc('s.id')->paginate(25,['s.id','s.admission_no','s.first_name','s.last_name','s.gender','s.status','s.admitted_on','s.photo_file_id']);
  $ids=$rows->pluck('id');$enrollments=DB::table('enrollments as e')->join('sections as s','s.id','=','e.section_id')->join('classes as c','c.id','=','s.class_id')->join('campuses as p','p.id','=','s.campus_id')->join('academic_sessions as y','y.id','=','s.academic_session_id')->where('e.school_id',$sid)->whereIn('e.student_id',$ids)->whereIn('s.campus_id',$campuses)->orderByDesc('e.starts_on')->orderByDesc('e.id')->get(['e.student_id','e.status','c.name as class_name','s.name as section_name','p.name as campus_name','y.name as session_name'])->groupBy('student_id');
  foreach($rows as $row)$row->placement=$enrollments->get($row->id)?->first();
  return response()->json($rows);
 }
 public function show(Request $r,int $student){[$sid,$campuses]=$this->students->context($r);$s=$this->students->student($sid,$campuses,$student);$manage=$this->students->access->can($r,'students.manage');if(!$manage){unset($s->identity_number,$s->identity_type);}
  $guardians=DB::table('student_guardians as l')->join('guardians as g','g.id','=','l.guardian_id')->where('l.school_id',$sid)->where('l.student_id',$student)->orderByDesc('l.is_primary')->get(['g.*','l.relationship','l.is_primary','l.can_receive_reports','l.can_pick_up']);
  foreach($guardians as $g){if(!$manage)unset($g->cnic);$g->siblings=$this->students->visible($sid,$campuses)->where('s.id','<>',$student)->whereExists(fn($q)=>$q->selectRaw('1')->from('student_guardians as l')->whereColumn('l.student_id','s.id')->whereColumn('l.school_id','s.school_id')->where('l.guardian_id',$g->id))->get(['s.id','s.first_name','s.last_name','s.admission_no']);}
  $history=DB::table('enrollments as e')->join('sections as s','s.id','=','e.section_id')->join('classes as c','c.id','=','s.class_id')->join('campuses as p','p.id','=','s.campus_id')->join('academic_sessions as y','y.id','=','s.academic_session_id')->where('e.school_id',$sid)->where('e.student_id',$student)->whereIn('s.campus_id',$campuses)->orderByDesc('e.starts_on')->orderByDesc('e.id')->get(['e.*','c.name as class_name','s.name as section_name','s.campus_id','p.name as campus_name','y.name as session_name']);
  return response()->json(['student'=>$s,'guardians'=>$guardians,'history'=>$history,'documents'=>$manage?DB::table('student_documents as d')->join('files as f','f.id','=','d.file_id')->where('d.school_id',$sid)->where('d.student_id',$student)->get(['d.id','d.file_id','d.document_type','f.original_name','f.size_bytes','f.created_at']):[],'can_manage'=>$manage]);
 }
 public function store(Request $r){$id=$this->locked($r,fn($sid,$campuses)=>$this->students->admit($r,$r->all(),$sid,$campuses));return response()->json(['id'=>$id,'message'=>'Student admitted.']);}
 public function update(Request $r,int $student){$this->locked($r,function($sid,$campuses)use($r,$student){$s=$this->students->student($sid,$campuses,$student,true);$d=$this->students->profile($r->all(),$sid,$student);$earliest=DB::table('enrollments')->where('school_id',$sid)->where('student_id',$student)->min('starts_on');if($earliest&&$d['admitted_on']>$earliest)$this->students->fail('Admission date cannot be after the first enrollment.');DB::table('students')->where('school_id',$sid)->where('id',$student)->update($d+['updated_at'=>now()]);$this->students->access->audit($r,'students.profile_updated','students',$student,['fields'=>array_keys($d)]);});return response()->json(['message'=>'Student profile saved.']);}
 public function guardians(Request $r){[$sid,$campuses]=$this->students->context($r,true);$d=$r->validate(['search'=>'nullable|string|max:100','page'=>'nullable|integer|min:1']);$q=DB::table('guardians as g')->where('g.school_id',$sid)->whereExists(fn($q)=>$q->selectRaw('1')->from('student_guardians as l')->whereColumn('l.guardian_id','g.id')->whereColumn('l.school_id','g.school_id')->whereIn('l.student_id',$this->students->visible($sid,$campuses)->select('s.id')));if(!empty($d['search']))$q->where(fn($q)=>$q->where('g.name','like','%'.$d['search'].'%')->orWhere('g.phone','like','%'.$d['search'].'%'));return response()->json($q->orderBy('g.name')->paginate(25,['g.*']));}
 public function saveGuardian(Request $r,int $guardian){$this->locked($r,function($sid,$campuses)use($r,$guardian){$this->students->guardian($sid,$campuses,$guardian,true);$d=$this->students->guardianData($r->all(),$sid,$guardian);DB::table('guardians')->where('school_id',$sid)->where('id',$guardian)->update($d+['updated_at'=>now()]);$this->students->access->audit($r,'students.guardian_updated','guardians',$guardian,['fields'=>array_keys($d)]);});return response()->json(['message'=>'Guardian saved for all linked siblings.']);}
 public function link(Request $r,int $student){$this->locked($r,function($sid,$campuses)use($r,$student){$this->students->student($sid,$campuses,$student,true);$d=$this->students->relation($r->all());$gid=$r->validate(['guardian_id'=>'nullable|integer'])['guardian_id']??null;
   if($gid)$this->students->guardian($sid,$campuses,$gid,true);else $gid=DB::table('guardians')->insertGetId($this->students->guardianData($r->all(),$sid)+['school_id'=>$sid,'created_at'=>now(),'updated_at'=>now()]);
   if(!$d['is_primary']&&!DB::table('student_guardians')->where('school_id',$sid)->where('student_id',$student)->where('guardian_id','<>',$gid)->where('is_primary',true)->exists())$this->students->fail('Keep one primary guardian. Mark this guardian primary or choose another first.');
   if($d['is_primary'])DB::table('student_guardians')->where('school_id',$sid)->where('student_id',$student)->update(['is_primary'=>false,'updated_at'=>now()]);
   DB::table('student_guardians')->updateOrInsert(['school_id'=>$sid,'student_id'=>$student,'guardian_id'=>$gid],$d+['updated_at'=>now()]);$this->students->access->audit($r,'students.guardian_linked','students',$student,['guardian_id'=>$gid,'relationship'=>$d['relationship']]);});return response()->json(['message'=>'Guardian relationship saved.']);}
 public function unlink(Request $r,int $student,int $guardian){$this->locked($r,function($sid,$campuses)use($r,$student,$guardian){$this->students->student($sid,$campuses,$student,true);$link=DB::table('student_guardians')->where('school_id',$sid)->where('student_id',$student)->where('guardian_id',$guardian)->first()??abort(404);if($link->is_primary)$this->students->fail('Choose another primary guardian before removing this link.');DB::table('student_guardians')->where('id',$link->id)->where('school_id',$sid)->delete();$this->students->access->audit($r,'students.guardian_unlinked','students',$student,['guardian_id'=>$guardian]);});return response()->json(['message'=>'Guardian link removed.']);}
 public function enrollment(Request $r,int $student){$this->locked($r,function($sid,$campuses)use($r,$student){$s=$this->students->student($sid,$campuses,$student,true);$d=$r->validate(['action'=>['required',Rule::in(['move','withdraw','readmit'])],'section_id'=>'required_unless:action,withdraw|nullable|integer','effective_on'=>'required|date_format:Y-m-d|after_or_equal:'.$s->admitted_on,'roll_no'=>'nullable|string|max:30','reason'=>'required|string|min:5|max:1000']);
   $active=DB::table('enrollments')->where('school_id',$sid)->where('student_id',$student)->where('status','active')->get();if($active->count()>1)$this->students->fail('Multiple active enrollments need review before this transition.');$old=$active->first();
   if($d['action']==='readmit'){if(!in_array($s->status,['withdrawn','graduated'],true)||$old)$this->students->fail('Readmission requires a withdrawn or graduated student.');$this->students->limit($sid);}else{if($s->status!=='active'||!$old)$this->students->fail('No active enrollment to change.');if($d['effective_on']<=$old->starts_on)$this->students->fail('Change date must be after the current enrollment start.');}
   $end=\Carbon\CarbonImmutable::parse($d['effective_on'])->subDay()->toDateString();
   if($d['action']==='withdraw'&&$d['effective_on']>now('Asia/Karachi')->toDateString())$this->students->fail('Withdrawal cannot be scheduled in the future.');
   if($d['action']==='move'&&$d['effective_on']>now('Asia/Karachi')->toDateString())$this->students->fail('Use today or a past date for a class change. Future promotion scheduling will be separate.');
   if($d['action']!=='withdraw'){
    $sec=$this->students->section($sid,$campuses,(int)$d['section_id'],$d['effective_on']);if($old&&$old->section_id==$sec->id)$this->students->fail('Choose a different section.');
    if(DB::table('enrollments')->where('school_id',$sid)->where('student_id',$student)->when($old,fn($q)=>$q->where('id','<>',$old->id))->where(fn($q)=>$q->whereNull('ends_on')->orWhere('ends_on','>=',$d['effective_on']))->exists())$this->students->fail('This date overlaps an existing enrollment history.');
    $this->students->capacity($sec,$sid,$d['effective_on'],$d['roll_no']??null);
   }
   // Never move history underneath attendance/results/fees already dated after the close.
   if($old){foreach(['attendance_records'=>'enrollment_id','test_results'=>'enrollment_id','invoices'=>'enrollment_id'] as $table=>$column)if(DB::table($table)->where('school_id',$sid)->where($column,$old->id)->exists()&&$d['effective_on']<now('Asia/Karachi')->toDateString())$this->students->fail('Linked attendance, results or invoices prevent a backdated change. Use today and retain history.');DB::table('enrollments')->where('school_id',$sid)->where('id',$old->id)->update(['status'=>$d['action']==='withdraw'?'withdrawn':'completed','ends_on'=>$end,'updated_at'=>now()]);}
   if($d['action']!=='withdraw')DB::table('enrollments')->insert(['school_id'=>$sid,'student_id'=>$student,'section_id'=>$sec->id,'roll_no'=>$d['roll_no']??null,'starts_on'=>$d['effective_on'],'status'=>'active','created_at'=>now(),'updated_at'=>now()]);
   DB::table('students')->where('school_id',$sid)->where('id',$student)->update(['status'=>$d['action']==='withdraw'?'withdrawn':'active','updated_at'=>now()]);$this->students->access->audit($r,'students.'.$d['action'],'students',$student,['effective_on'=>$d['effective_on'],'reason'=>$d['reason'],'old_enrollment_id'=>$old?->id,'section_id'=>$d['section_id']??null]);});return response()->json(['message'=>'Enrollment history updated.']);}
 public function upload(Request $r,int $student){[$sid,$campuses]=$this->students->context($r,true);$this->students->student($sid,$campuses,$student,true);$d=$r->validate(['document_type'=>['required',Rule::in(['photo','birth_certificate','b_form','previous_school_certificate','other'])],'file'=>['required','file','max:5120','mimes:pdf,jpg,jpeg,png']]);$file=$r->file('file');if($d['document_type']==='photo'&&!str_starts_with($file->getMimeType(),'image/'))$this->students->fail('Photo must be a JPEG or PNG image.');
  $path=$file->store('schools/'.$sid.'/students/'.$student,'local');if(!$path)$this->students->fail('File storage failed. Please retry.');
  try{$id=$this->locked($r,function($sid,$campuses)use($r,$student,$d,$file,$path){$this->students->student($sid,$campuses,$student,true);$fid=DB::table('files')->insertGetId(['school_id'=>$sid,'uploaded_by'=>$this->students->access->membership($r)->id,'disk'=>'local','path'=>$path,'original_name'=>mb_substr(basename($file->getClientOriginalName()),0,160),'mime_type'=>$file->getMimeType(),'size_bytes'=>$file->getSize(),'created_at'=>now(),'updated_at'=>now()]);$id=DB::table('student_documents')->insertGetId(['school_id'=>$sid,'student_id'=>$student,'file_id'=>$fid,'document_type'=>$d['document_type'],'created_at'=>now(),'updated_at'=>now()]);if($d['document_type']==='photo')DB::table('students')->where('school_id',$sid)->where('id',$student)->update(['photo_file_id'=>$fid,'updated_at'=>now()]);$this->students->access->audit($r,'students.document_uploaded','students',$student,['document_id'=>$id,'document_type'=>$d['document_type']]);return $id;});}catch(\Throwable $e){Storage::disk('local')->delete($path);throw $e;}return response()->json(['id'=>$id,'message'=>'Private document uploaded.']);}
 public function photo(Request $r,int $student){[$sid,$campuses]=$this->students->context($r);$s=$this->students->student($sid,$campuses,$student);abort_unless($s->photo_file_id,404);$f=DB::table('files')->where('school_id',$sid)->where('id',$s->photo_file_id)->where('disk','local')->whereIn('mime_type',['image/jpeg','image/png'])->first()??abort(404);abort_unless(DB::table('student_documents')->where('school_id',$sid)->where('student_id',$student)->where('file_id',$f->id)->where('document_type','photo')->exists()&&Storage::disk('local')->exists($f->path),404);return Storage::disk('local')->response($f->path,'photo',['Cache-Control'=>'private, no-store','X-Content-Type-Options'=>'nosniff'],'inline');}
 public function download(Request $r,int $student,int $file){[$sid,$campuses]=$this->students->context($r,true);$this->students->student($sid,$campuses,$student);abort_unless(DB::table('student_documents')->where('school_id',$sid)->where('student_id',$student)->where('file_id',$file)->exists(),404);$f=DB::table('files')->where('school_id',$sid)->where('id',$file)->where('disk','local')->first()??abort(404);abort_unless(Storage::disk('local')->exists($f->path),404);return Storage::disk('local')->download($f->path,$f->original_name,['Cache-Control'=>'private, no-store','X-Content-Type-Options'=>'nosniff']);}
}
